import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';
const sourceDir='data/recipes/modern-scale-20261021b-arabic';const finalDir='data/recipes/arabic-youtube/manal-scale-20261021b';fs.mkdirSync(path.join(finalDir,'source-extracts'),{recursive:true});
const batch=JSON.parse(fs.readFileSync(path.join(sourceDir,'recipes.json'),'utf8'));
for(const r of batch.recipes){const old=r.sourceEvidence.sourceExtractFile;const name=path.basename(old);const newRel=path.join(finalDir,'source-extracts',name).replaceAll('\\','/');const note=fs.readFileSync(old);fs.writeFileSync(newRel,note);r.sourceEvidence.sourceExtractFile=newRel;const copy={...r};delete copy.contentSha256;r.contentSha256=createHash('sha256').update(JSON.stringify((function sort(v){return Array.isArray(v)?v.map(sort):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])])):v})(copy)),'utf8').digest('hex');}
for(const entry of batch.sourceIndex){entry.extractFile=path.join(finalDir,'source-extracts',path.basename(entry.extractFile)).replaceAll('\\','/');}
batch.counts.failed=1;batch.counts.failedRequests=1;batch.counts.retrievalAttempts=batch.underlyingHttpRequestCount;batch.finalPackPath=path.join(finalDir,'finalpackrecipes.json').replaceAll('\\','/');batch.stage='facts-research-final-pack-pending-parent-review';
const out=path.join(finalDir,'finalpackrecipes.json');fs.writeFileSync(out,JSON.stringify(batch,null,2)+'\n','utf8');const bytes=fs.readFileSync(out);console.log(JSON.stringify({path:out,sha256:createHash('sha256').update(bytes).digest('hex'),records:batch.recipes.length,ingredients:batch.counts.sourceIngredients,steps:batch.counts.sourceMethodSteps,requests:batch.underlyingHttpRequestCount,failedRequests:batch.counts.failedRequests,extracts:batch.recipes.length}));
